 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    mark = set()
    # Recolor contiguous runs of 4s that are bounded by 9s on both ends.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 4:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] == 4:
                c += 1
            if start > 0 and c < w and grid[r][start - 1] == 9 and grid[r][c] == 9:
                for x in range(start, c):
                    mark.add((r, x))
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 4:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] == 4:
                r += 1
            if start > 0 and r < h and grid[start - 1][c] == 9 and grid[r][c] == 9:
                for y in range(start, r):
                    mark.add((y, c))
    for r, c in mark:
        out[r][c] = 2
    return out

if __name__ == '__main__':
    pass
